class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{int tab=0;int? zone,ward;void nav(int i)=>setState(()=>tab=i);void add(String what){showDialog(context:context,builder:(_)=>AlertDialog(title:Text('Add $what'),content:TextField(keyboardType:TextInputType.number,decoration:InputDecoration(labelText:'$what No',border:const OutlineInputBorder())),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('CANCEL')),FilledButton(onPressed:()=>Navigator.pop(context),child:const Text('ADD'))]));}
