class Btn extends StatelessWidget{final String t;final IconData icon;final VoidCallback onTap;const Btn(this.t,this.icon,this.onTap,{super.key});@override Widget build(BuildContext c)=>FilledButton.icon(onPressed:onTap,icon:Icon(icon),label:Text(t,textAlign:TextAlign.center),style:FilledButton.styleFrom(padding:const EdgeInsets.all(18)));}
class Shell extends StatelessWidget{final Widget child;final int index;const Shell({super.key,required this.child,required this.index});@override Widget build(BuildContext c)=>Scaffold(body:child,bottomNavigationBar:Nav(index:index,onTap:(i){if(i==0)Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>const Home()));else if(i==1)Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>const Gsm()));else if(i==2)Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>const Lora()));else Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>const MapPage()));}));}
