class MapPage extends StatefulWidget{const MapPage({super.key});@override State<MapPage> createState()=>_MapState();}
class _MapState extends State<MapPage>{final MapController map=MapController();final List<Marker> markers=[Marker(point:const LatLng(12.9716,77.5946),width:44,height:44,child:const Icon(Icons.location_pin,size:44,color:Colors.red))];final List<String> valves=['GSM-001','GSM-002','LoRa-001'];void addValve(){setState(()=>valves.add('GSM-${(valves.length+1).toString().padLeft(3,'0')}'));} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('MAP'),actions:[IconButton(onPressed:addValve,icon:const Icon(Icons.add_location_alt))]),body:Column(children:[Padding(padding:const EdgeInsets.all(10),child:Row(children:[const Expanded(child:Text('Municipal Valve Map',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold))),FilledButton.icon(onPressed:addValve,icon:const Icon(Icons.add),label:const Text('ADD VALVE'))])),Expanded(child:FlutterMap(mapController:map,options:const MapOptions(initialCenter:LatLng(12.9716,77.5946),initialZoom:12),children:[TileLayer(urlTemplate:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',userAgentPackageName:'com.municipal.operator'),MarkerLayer(markers:markers)])),const Padding(padding:EdgeInsets.all(10),child:Align(alignment:Alignment.centerLeft,child:Text('Valve List',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold))),),Expanded(child:ListView.builder(itemCount:valves.length,itemBuilder:(c,i)=>ListTile(leading:const Icon(Icons.location_pin,color:Colors.red),title:Text('Valve ID: ${valves[i]}'),subtitle:const Text('Latitude / Longitude'),trailing:IconButton(onPressed:(){},icon:const Icon(Icons.link)))))]));}
